'use strict';

/**
* Format an array of reference tokens into a JSON Pointer string.
*
* @module @stdlib/utils-json-pointer-format
*
* @example
* var format = require( '@stdlib/utils-json-pointer-format' );
*
* var ptr = format( [ 'foo', 'bar' ] );
* // returns '/foo/bar'
*
* ptr = format( [ 'a/b', 'c~d' ] );
* // returns '/a~1b/c~0d'
*
* ptr = format( [] );
* // returns ''
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
