'use strict';

// MODULES //

var isStringArray = require( '@stdlib/assert-is-string-array' ).primitives;
var isArray = require( '@stdlib/assert-is-array' );
var replace = require( '@stdlib/string-base-replace' );
var format = require( '@stdlib/string-format' );


// MAIN //

/**
* Formats an array of reference tokens into a JSON Pointer string.
*
* ## Notes
*
* -   Implements formatting per RFC 6901.
* -   An empty array returns an empty string (i.e., refers to the root of the document).
* -   Escape sequences are encoded. During encoding, `~` is escaped to `~0` before `/` is escaped to `~1`.
*
* @param {Array<string>} tokens - array of reference tokens
* @throws {TypeError} must provide an array of strings
* @returns {string} JSON Pointer string
*
* @example
* var ptr = formatPointer( [ 'foo', 'bar' ] );
* // returns '/foo/bar'
*
* @example
* var ptr = formatPointer( [ 'a/b', 'c~d' ] );
* // returns '/a~1b/c~0d'
*
* @example
* var ptr = formatPointer( [] );
* // returns ''
*/
function formatPointer( tokens ) {
	var out;
	var i;

	if ( isArray( tokens ) && tokens.length === 0 ) {
		return '';
	}
	if ( !isStringArray( tokens ) ) {
		throw new TypeError( format( 'invalid argument. Must provide an array of strings. Value: `%s`.', tokens ) );
	}
	out = '';

	// Escape reference tokens per RFC 6901 (note: '~' must be replaced before '/' to avoid corrupting sequences such as '~1'):
	for ( i = 0; i < tokens.length; i++ ) {
		out += '/' + replace( replace( tokens[ i ], /~/g, '~0' ), /\//g, '~1' );
	}
	return out;
}


// EXPORTS //

module.exports = formatPointer;
